import re

result = []

# 删除以下类型内容：
# !image-xxx.png!
# !screenshot-xxx.png!
# !screenshot-xxx.png|thumbnail!
# [~username]  (username 任意)
pattern = re.compile(
    r'!https://media-cdn\.atlassian\.com/[^!\s]+!|!(?:image|screenshot)-[\w\-]+\.png(?:\|thumbnail)?!|\[~[^\]]+\]'
)

exclude_keywords = ["详细信息请参见链接"]

for item in items:
    comments = item.get("json", {}).get("comments", [])

    for comment in comments:
        # 跳过包含排除关键词的评论
        if any(keyword in comment for keyword in exclude_keywords):
            continue

        # 删除匹配内容，并合并多余空格
        cleaned = re.sub(pattern, '', comment)
        cleaned = re.sub(r'\s+', ' ', cleaned).strip()

        if cleaned:
            result.append(cleaned)

return [{
    "json": {
        "comments": result
    }
}]

