    if raw_text.strip():
        # ① 清理 <think>
        cleaned_text = think_pattern.sub("", raw_text).strip()

        # ② 匹配所有字段
        matches = field_pattern.findall(cleaned_text)

        # ③ 提取各字段
        for field, value, _ in matches:
            field_lower = field.lower().strip()
            val = safe_str(value).strip()
