from difflib import SequenceMatcher

SIMILARITY_THRESHOLD = 0.85

def is_similar(a, b):
    return SequenceMatcher(None, a, b).ratio() >= SIMILARITY_THRESHOLD


items = _input.all()
result = ""
for item in items:
    comments = item.json.get("comments", [])
    deduped = []

    for c in comments:
        is_dup = False
        for d in deduped:
            if is_similar(c, d):
                is_dup = True
                break

        if not is_dup:
            deduped.append(c)

    item.json["comments"] = deduped
result = "\n".join(item.json["comments"])

return {"comments_list": item.json["comments"],
       "comment_conbine": result}

